function Inspections(props: Props) {
  const [status, setStatus] = useState("EM CAMPO");
  const [submitted, setSubmitted] = useState(false);
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setSubmitted(true); setStatus("EM REVISÃO"); props.onToast("VS-204 recebida com geolocalização, fotos e checklist; QA iniciado"); };
  return <div className="twin-view"><section className="twin-inspection-summary">{[["Solicitadas","7","2 críticas","alert"],["Em campo","3","SLA médio 18 min","info"],["Em revisão","2","1 inconsistência","watch"],["Concluídas","18","últimas 24h","ok"]].map(([label,value,note,tone]) => <article className="panel" key={label}><span>{label}</span><strong>{value}</strong><small>{note}</small><Pill tone={tone as Tone}>LIVE</Pill></article>)}</section><article className="panel twin-workflow"><PanelHead eyebrow="WORKFLOW DE VISTORIA" title="VS-204 · D04-02 · pré-evento" side={<Pill tone={status === "EM REVISÃO" ? "watch" : "info"}>{status}</Pill>} /><div>{[["1","Solicitada","18:45:32"],["2","Despachada","18:46:05"],["3","Em campo","18:56:18"],["4","Revisão","pendente"],["5","Concluída","pendente"]].map(([id,name,time],index) => <span className={index <= (status === "EM REVISÃO" ? 3 : 2) ? "active" : ""} key={id}><i>{index < (status === "EM REVISÃO" ? 3 : 2) ? "✓" : id}</i><strong>{name}</strong><small>{time}</small>{index < 4 ? <b>→</b> : null}</span>)}</div></article><section className="twin-inspection-grid"><form className="panel twin-inspection-form" onSubmit={submit}><PanelHead eyebrow="FORMULÁRIO DE CAMPO" title="Checklist · drenagem D-04" side={<Pill tone="ok">FIELD MAPS</Pill>} /><div className="twin-auto-fields"><span><small>Usuário</small><strong>Equipe HSE-02</strong></span><span><small>Timestamp</small><strong>18:58:11</strong></span><span><small>Localização</small><strong>−20.285, −40.252</strong></span><span><small>Ativo</small><strong>D04-02</strong></span></div><fieldset><legend>Condição observada</legend>{["Acesso desobstruído","Alimentação elétrica disponível","Bomba operacional","Sem vazamento aparente","Gradeamento limpo"].map((item,index) => <label key={item}><input type="checkbox" defaultChecked={index < 3} />{item}</label>)}</fieldset><div className="twin-form-row"><label>Nível medido<input defaultValue="0,31 m" /></label><label>Rotação observada<select><option>Operacional</option><option>Parada</option><option>Não verificada</option></select></label></div><label>Observação<textarea defaultValue="Fluxo aparente normal; grade com obstrução parcial estimada em 20%." /></label><div className="twin-photo-drop"><span>＋</span><strong>Adicionar fotos e vídeo</strong><small>2 evidências já anexadas · GPS obrigatório</small></div><footer><button type="button" onClick={() => props.onToast("Rascunho offline salvo no dispositivo")}>Salvar offline</button><button className="twin-primary">Enviar vistoria</button></footer></form><aside className="panel twin-inspection-side"><PanelHead eyebrow="QA DA VISTORIA" title={submitted ? "Inconsistência detectada" : "Evidências em tempo real"} side={<Pill tone={submitted ? "critical" : "info"}>{submitted ? "BLOCK" : "LIVE"}</Pill>} />{submitted ? <><div className="twin-qa-conflict"><span><small>FORMULÁRIO</small><strong>Bomba operacional</strong></span><b>≠</b><span><small>SENSOR</small><strong>RPM = 0</strong></span></div><p>Não é possível concluir a vistoria até reconciliar a divergência ou anexar evidência do teste funcional.</p><button onClick={() => { setStatus("CONCLUÍDA"); props.onToast("Teste funcional confirmado; VS-204 concluída com evidência"); }}>Anexar teste e resolver</button></> : <>{[["Foto 01","Gradeamento norte","GPS OK"],["Foto 02","Painel D04-02","GPS OK"],["Vídeo","Teste funcional","pendente"]].map(([type,name,state]) => <div className="twin-evidence-row" key={type}><span>{type.slice(0,2)}</span><p><strong>{name}</strong><small>{type} · 18:57</small></p><b>{state}</b></div>)}<p>Tipos disponíveis: pré-evento, pós-evento, condição, liberação, manutenção, integridade e ambiental.</p></>}</aside></section></div>;
}

function Releases(props: Props) {
  const [step, setStep] = useState(3);
  const [partial, setPartial] = useState(true);
  return <div className="twin-view"><article className="panel twin-release-hero"><div><span>ASSET RELEASE · AR-204</span><h2>Liberação segura da C17</h2><p>Evento controlado → inspeção → evidências → limiares → dependências → teste → aprovação.</p></div><Pill tone={step >= 7 ? "ok" : "watch"}>{step >= 7 ? "RELEASED" : "PENDING"}</Pill><button onClick={() => setStep(Math.min(7, step + 1))}>{step >= 7 ? "Ver certificado" : "Avançar workflow"}</button></article><article className="panel twin-release-flow"><PanelHead eyebrow="WORKFLOW CONTROLADO" title="Nenhuma liberação silenciosa" side={<span>{step}/7 etapas</span>} /><div>{[["Evento controlado","HS-882 recuando"],["Inspeção","VS-204 aprovada"],["Evidências","4 anexos"],["Limiares","todos abaixo"],["Dependências","SE-04 estável"],["Teste funcional","15 min"],["Aprovação","Gerente turno"]].map(([name,note],index) => <span className={index < step ? "done" : index === step ? "active" : ""} key={name}><i>{index < step ? "✓" : index+1}</i><strong>{name}</strong><small>{note}</small>{index < 6 ? <b>→</b> : null}</span>)}</div></article><section className="twin-release-grid"><article className="panel twin-release-form"><PanelHead eyebrow="CONDIÇÃO DE RETORNO" title="Liberação parcial ou total" side={<Pill tone="info">HUMAN APPROVAL</Pill>} /><div className="twin-release-choice"><button className={partial ? "active" : ""} onClick={() => setPartial(true)}><strong>PARCIAL</strong><span>50%</span><small>por 2 horas</small></button><button className={!partial ? "active" : ""} onClick={() => setPartial(false)}><strong>TOTAL</strong><span>100%</span><small>operação normal</small></button></div><label>Capacidade inicial<input value={partial ? "1.400 t/h · 50%" : "2.800 t/h · 100%"} readOnly /></label><label>Validade<input value={partial ? "2 horas · revisão automática" : "sem prazo · monitoramento ativo"} readOnly /></label><label>Condição de reversão<textarea defaultValue="Reverter se vibração > 8,5 mm/s, nível D-04 > 0,40 m ou perda de SE-04." /></label><footer><button onClick={() => props.onToast("Minuta de liberação AR-204 exportada")}>Gerar minuta</button><button className="twin-primary" onClick={() => { setStep(7); props.onToast(`C17 liberada em ${partial ? "50% por 2h" : "100%"}; evento asset.released publicado`); }}>Aprovar e liberar</button></footer></article><aside className="panel twin-release-evidence"><PanelHead eyebrow="EVIDENCE PACK" title="Pronto para assinatura" side={<Pill tone="ok">6/6</Pill>} />{[["HS-882","Recessão confirmada","ok"],["VS-204","Inspeção aprovada","ok"],["VIB-C17-03","7,1 mm/s","ok"],["D-04","Nível 0,22 m","ok"],["Dependências","SE-04 estável","ok"],["Teste C17","15 min sem alarme","ok"]].map(([id,note,tone]) => <div key={id}><span className={`tone-${tone}`}>✓</span><p><strong>{id}</strong><small>{note}</small></p><button onClick={() => props.onToast(`${id}: evidência original aberta`)}>›</button></div>)}</aside></section></div>;
}

function Twin3D(props: Props) {
  const [level, setLevel] = useState(43);
  const [mode, setMode] = useState("Exposição");
  return <div className="twin-view"><section className="twin-scene-layout"><article className="panel twin-scene-panel"><PanelHead eyebrow="WEBSCENE · OPERATIONAL 3D" title="SE-04 · inundação sobre infraestrutura" side={<div className="twin-head-actions">{["Estado","Exposição","Capacidade"].map(item=><button className={mode===item?"active":""} onClick={()=>setMode(item)} key={item}>{item}</button>)}</div>} /><div className="twin-scene"><div className="twin-scene-map">{props.renderMap()}</div><div className="scene-ground" /><div className="scene-water" style={{ height:`${42 + level*.55}px` }}><span>P90 · {(level/100).toFixed(2)} m</span></div><div className="scene-building substation"><i /><i /><i /><strong>SE-04</strong></div><div className="scene-building transformer t1"><i /><strong>TR-01</strong></div><div className="scene-building transformer t2"><i /><strong>TR-02</strong></div><div className="scene-building panel-low"><i /><strong>PA-04</strong><small>abaixo da lâmina</small></div><div className="scene-compass">N<br />↑</div><div className="scene-mode">{mode.toUpperCase()} · WEBSCENE TUB-OPS-04</div></div><div className="twin-scene-time"><button>▶</button><span>18:30</span><input type="range" min="0" max="60" value={level} onChange={event=>setLevel(Number(event.target.value))} /><span>23:40</span><strong>{(level/100).toFixed(2)} m</strong></div></article><aside className="panel twin-scene-inspector"><PanelHead eyebrow="3D INSPECTOR" title="SE-04" side={<Pill tone="alert">EXPOSED</Pill>} /><div className="twin-scene-selection"><span>SE</span><div><strong>Subestação SE-04</strong><small>assetId compartilhado 2D / 3D</small></div></div><dl><div><dt>Lâmina P90</dt><dd>{(level/100).toFixed(2)} m</dd></div><div><dt>Transformadores</dt><dd>acima da cota</dd></div><div><dt>Painel auxiliar</dt><dd>abaixo da cota</dd></div><div><dt>Falha P90</dt><dd>61%</dd></div><div><dt>SceneLayer</dt><dd>TUB-STRUCT-03</dd></div><div><dt>Confidence</dt><dd>79%</dd></div></dl><h3>Estratégia de camada</h3>{[["FeatureLayer","Ativos e estado"],["SceneLayer","Estruturas 3D"],["BuildingSceneLayer","BIM selecionado"],["Integrated Mesh","Contexto do terminal"]].map(([type,note])=><div className="twin-layer-strategy" key={type}><span>{type.slice(0,2)}</span><p><strong>{type}</strong><small>{note}</small></p><Pill tone="ok">ON</Pill></div>)}<button onClick={() => props.onToast("Objeto BIM SE-04 aberto mantendo assetId e SelectionContext")}>Abrir BIM selecionado</button></aside></section></div>;
}

function Processes(props: Props) {
  const [cockpit, setCockpit] = useState("Terminal");
  return <div className="twin-view"><article className="panel twin-process-hero"><PanelHead eyebrow="PROCESS TWIN" title="Minério · trem ao navio" side={<Pill tone="watch">1 RESTRIÇÃO</Pill>} /><div>{[["Trem","EFVM","ok"],["Virador","VV-02","ok"],["Pátio","PN-04","watch"],["Correia","C17","alert"],["Planta","P3","watch"],["Pátio produto","PP-02","ok"],["Shiploader","SL-03","watch"],["Navio","B2","info"]].map(([name,id,tone],index)=><span key={id}><i className={`tone-${tone}`}>{id}</i><strong>{name}</strong><small>{id === "C17" ? "2.300 t/h" : id === "P3" ? "−7% previsto" : "operacional"}</small>{index<7?<b>→</b>:null}</span>)}</div><footer><span>M4 mostra o estado do componente; M5 otimiza a cadeia.</span><button onClick={props.onChain}>Abrir otimização no M5</button></footer></article><section className="twin-process-grid"><aside className="panel twin-cockpit-list"><PanelHead eyebrow="COCKPITS OPERACIONAIS" title="Sistemas integrados" />{["Reservatórios","Drenagem","Pátio","Planta","Terminal","Ferrovia / Recebimento","Energia","Vias & Acessos"].map((item,index)=><button className={cockpit===item?"active":""} onClick={()=>setCockpit(item)} key={item}><span>{String(index+1).padStart(2,"0")}</span><strong>{item}</strong><small>{index===1?"1 estação crítica":index===4?"2 restrições":"normal"}</small><b>›</b></button>)}</aside><article className="panel twin-process-cockpit"><PanelHead eyebrow="SYSTEM COCKPIT" title={cockpit} side={<Pill tone={cockpit==="Drenagem"||cockpit==="Terminal"?"watch":"ok"}>LIVE</Pill>} /><div className="twin-process-metrics">{[["Disponibilidade","94,2%"],["Capacidade","92,4%"],["Ativos críticos","12"],["Alertas","3"]].map(([label,value])=><span key={label}><small>{label}</small><strong>{value}</strong></span>)}</div><div className="twin-process-chart">{[84,88,91,86,82,78,74,80,88,92,94,96].map((value,index)=><i key={index} style={{height:`${value}%`}} className={value<80?"critical":""} />)}</div><table><thead><tr><th>Ativo</th><th>Estado</th><th>Capacidade</th><th>Exposição</th><th>Ação</th></tr></thead><tbody>{assets.slice(0,4).map(item=><tr key={item.id}><td><strong>{item.id}</strong></td><td><Pill tone={item.tone}>{item.state}</Pill></td><td>{item.capacity}</td><td>{item.exposure}</td><td><button onClick={()=>props.onSelectAsset(item.id)}>Abrir</button></td></tr>)}</tbody></table></article></section></div>;
}

function Agents(props: Props) {
  return <div className="twin-view"><article className="panel twin-agent-hero"><div><span>AGENTIC ASSET OPERATIONS</span><h2>12 agentes para exposição, condição, despacho e liberação</h2><p>Automação rastreável, exceção explícita e decisão humana nos pontos de risco.</p></div><div>{["PERIGO","EXPOSIÇÃO","ESTADO","CAPACIDADE","AÇÃO","LIBERAÇÃO"].map((item,index)=><span key={item}><i>{index+1}</i>{item}{index<5?<b>→</b>:null}</span>)}</div></article><section className="twin-agent-grid">{agents.map(([name,role,state,guardrail],index)=><article className="panel twin-agent-card" key={name}><header><span>AI</span><div><small>AGENTE {String(index+1).padStart(2,"0")}</small><h3>{name}</h3></div><Pill tone={index===4||index===7?"critical":index===8?"watch":"ok"}>{index===4?"N+0":index===7?"REVIEW":index===8?"PENDING":"ACTIVE"}</Pill></header><p>{role}</p><dl><div><dt>Agora</dt><dd>{state}</dd></div><div><dt>Guardrail</dt><dd>{guardrail}</dd></div></dl><footer><button onClick={()=>props.onToast(`${name}: fontes, fatores e evidências abertas`)}>Evidências</button><button onClick={()=>props.onToast(`${name}: execução pausada; estado operacional preservado`)}>Pausar</button></footer></article>)}</section><article className="panel twin-event-stream"><PanelHead eyebrow="EVENT STREAM" title="Orquestração ponta a ponta · HS-882" side={<Pill tone="ok">LIVE</Pill>} /><div>{[["18:45:24","HS","HS-882 published","hazard.surface.published"],["18:45:25","EX","17 assets intersected","asset.exposure.detected"],["18:45:28","VU","2 high impacts","asset.predicted_state.changed"],["18:45:30","AG","C17 96 → 82","asset.capacity.changed"],["18:45:31","DP","M5 notified","asset.constraint.published"],["18:45:32","IN","VS-204 created","asset.inspection.requested"]].map(([time,agent,text,event],index)=><span className={index===5?"current":"done"} key={time}><time>{time}</time><i>{index<5?"✓":"●"}</i><b>{agent}</b><strong>{text}</strong><small>{event}</small></span>)}</div></article></div>;
}

function IntegrationsReports(props: Props) {
  const [report, setReport] = useState("Asset Situation Report");
  const reports = ["Asset Situation Report","Critical Asset Report","Exposure Report","Vulnerability Report","Capacity Forecast","Dependency Report","Redundancy Gap","Inspection Report","Asset Release Report","Post-event Report"];
  return <div className="twin-view"><article className="panel twin-integration-hero"><div><span>ARCGIS · GEOSPATIAL INTEGRATION BACKBONE</span><h2>Ativo, espaço, tempo e operação em um SelectionContext</h2><p>WebMap e WebScene compartilham assetId, timeExtent, scenarioId e fontes oficiais.</p></div><div className="twin-arcgis-mark"><span>GIS</span><strong>ArcGIS Maps SDK 5.1</strong><small>FeatureLayer · SceneLayer · Living Atlas</small></div></article><section className="twin-integration-grid"><article className="panel twin-architecture"><PanelHead eyebrow="INTERFACES CORPORATIVAS" title="Leitura, eventos e deep links" side={<Pill tone="ok">8/8 ONLINE</Pill>} /><div>{[["SCADA / DCS / PLC","estado · comando · alarmes","READ ONLY"],["Historian","séries temporais · qualidade","STREAM"],["EAM / CMMS","ativos · WO · manutenção","SYNC"],["MES","produção · modo operacional","EVENT"],["BIM / CAD","geometria · documentos","LINK"],["ArcGIS","mapa · cena · serviços","NATIVE"]].map(([name,data,mode],index)=><span key={name}><i>{index+1}</i><p><strong>{name}</strong><small>{data}</small></p><b>{mode}</b></span>)}</div></article><article className="panel twin-contracts"><PanelHead eyebrow="CONTRATOS ENTRE MÓDULOS" title="Espacial, temporal e auditável" />{[["M3 → M4","HazardSurface","HS-882"],["M4 → M5","AssetConstraint","AC-2084"],["M4 → M1","State / Capacity / Redundancy","event bus"],["M6 ↔ M4","Scenario AssetState","SANDBOX"],["M7 / M8","Vistoria / Emergência","workflow"],["M9 / M10","Auditoria / Dados","lineage"]].map(([flow,object,id],index)=><div key={flow}><span>{flow}</span><p><strong>{object}</strong><small>{id}</small></p><Pill tone={index===3?"watch":"ok"}>{index===3?"SCENARIO":"LIVE"}</Pill></div>)}</article></section><article className="panel twin-event-bus"><PanelHead eyebrow="EVENT BUS" title="Eventos operacionais publicados" side={<button onClick={()=>props.onToast("Payload asset.capacity.changed validado contra schema v4")}>Inspecionar payload</button>} /><div>{["asset.exposure.detected","asset.state.changed","asset.predicted_state.changed","asset.capacity.changed","asset.restriction.created","asset.failure.predicted","asset.redundancy.changed","asset.inspection.requested","asset.inspection.completed","asset.release.requested","asset.released"].map((event,index)=><span key={event}><i>{String(index+1).padStart(2,"0")}</i><strong>{event}</strong><small>{index<4?"operational-twin":"workflow-bus"}</small></span>)}</div></article><section className="twin-reports-grid"><aside className="panel twin-report-list"><PanelHead eyebrow="REPORT CATALOG" title="Entregáveis do M4" />{reports.map((item,index)=><button className={report===item?"active":""} onClick={()=>setReport(item)} key={item}><span>{index%3===0?"LIVE":"PDF"}</span><strong>{item}</strong><b>›</b></button>)}</aside><article className="panel twin-report-preview"><header><div><span>ATLAS CLIMA · GÊMEO OPERACIONAL</span><h2>{report}</h2><p>07 AGO 2026 · 19:02 BRT · situação LIVE</p></div><Pill tone="ok">VERSIONADO</Pill></header><section><div className="twin-report-metric"><span>Disponibilidade</span><strong>94,2%</strong><small>+0,6 pp</small></div><div className="twin-report-metric"><span>Capacidade</span><strong>92,4%</strong><small>−4,8 pp</small></div><div className="twin-report-metric"><span>Expostos 24h</span><strong>27</strong><small>2 críticos</small></div><div className="twin-report-metric"><span>Confidence</span><strong>79%</strong><small>6 fontes</small></div></section><div className="twin-report-chart">{[91,94,92,88,84,80,74,78,88,92,94,96].map((value,index)=><i key={index} style={{height:`${value}%`}} />)}</div><footer><span>Fontes: ArcGIS · SCADA · Historian · EAM · inspeções · HS-882</span><button onClick={()=>props.onToast(`${report} gerado e anexado à trilha de evidências`)}>Gerar report pack</button></footer></article></section></div>;
}

export function TwinModule(props: Props) {
  return useMemo(() => {
    if (props.subview === "Mapa de Ativos") return <MapAssets {...props} />;
    if (props.subview === "Cockpit do Ativo") return <Cockpit {...props} />;
    if (props.subview === "Exposição & Vulnerabilidade") return <ExposureVulnerability {...props} />;
    if (props.subview === "Capacidade & Restrições") return <CapacityRestrictions {...props} />;
    if (props.subview === "Dependências & Redundância") return <Dependencies {...props} />;
    if (props.subview === "Sensores & Saúde") return <SensorsHealth {...props} />;
    if (props.subview === "Manutenção") return <Maintenance {...props} />;
    if (props.subview === "Inspeções") return <Inspections {...props} />;
    if (props.subview === "Liberações") return <Releases {...props} />;
    if (props.subview === "Gêmeo 3D") return <Twin3D {...props} />;
    if (props.subview === "Processos") return <Processes {...props} />;
    if (props.subview === "Agentes") return <Agents {...props} />;
    if (props.subview === "Integrações & Relatórios") return <IntegrationsReports {...props} />;
    return <Situation {...props} />;
  }, [props]);
}
